import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../src/jobs/cleanup.js';

const broken = { deleteExpired: () => { throw new Error('db down at 10.0.0.5'); } };

test('cleanup: deletes the expired rows', () => {
  const res = run({ db: { deleteExpired: () => 4 } });
  assert.equal(res.status, 200);
  assert.equal(res.body.deleted, 4);
});

test('cleanup: a database error is a 500', () => {
  assert.equal(run({ db: broken }).status, 500);
});

test('cleanup: the 500 body does not carry the internal error text', () => {
  const res = run({ db: broken });
  assert.equal(res.body.error, 'internal error');
  assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
});
