import { test } from 'node:test';
import assert from 'node:assert/strict';
import { JOBS } from '../src/jobs/index.js';

// #9, #12: the 500 body is shown on the scheduler's admin screen, so it must not
// carry the internal error text (CONTRIBUTING.md「失敗の応答」).
// This runs over every job in JOBS, so a job added later is checked too.

const SECRET = 'db down at 10.0.0.5';

// A db whose every method throws, whatever the job calls on it.
const brokenDb = new Proxy({}, {
  get: () => () => { throw new Error(SECRET); },
});

test('JOBS is not empty', () => {
  assert.ok(Object.keys(JOBS).length > 0);
});

for (const [name, job] of Object.entries(JOBS)) {
  test(`${name}: the 500 body has the fixed message and no internal error text`, () => {
    const res = job.run({ db: brokenDb, email: 'a@example.com' });
    assert.equal(res.status, 500);
    assert.equal(res.body.error, 'internal error');
    assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
  });
}

